<template><view v-if="visible" class="overlay"><view class="dialog"><text class="title">欢迎使用与律行</text><text>第 {{step+1}} / 3 步</text><text class="heading">{{steps[step].title}}</text><text class="body">{{steps[step].body}}</text><view><button size="mini" @click="done">跳过</button><button size="mini" type="primary" @click="next">{{step===2?'开始使用':'下一步'}}</button></view></view></view></template>
<script>
export default{props:{refreshKey:{type:Number,default:0}},data(){return{visible:false,step:0,owner:'',steps:[{title:'先准备模板',body:'在模板管理中维护分类、上传原件并核对填写字段。上传或解析完成后，仍需人工确认。'},{title:'再起草文书',body:'选择已确认模板，填写真实要素，核对并保存正文，也可使用标准起草。切换底部入口会保留当前填写。'},{title:'其他法律工具',body:'工作台提供法律咨询、合同快审和案件入口；我的保留账户与历史功能。'}]};},watch:{refreshKey:{immediate:true,handler(){this.check();}}},methods:{check(){const info=uni.getStorageSync('userInfo')||{};this.owner=uni.getStorageSync('token')?String(info.userId||''):'';this.step=0;this.visible=Boolean(this.owner&&!uni.getStorageSync('lawyerOnboarding:v1:'+this.owner));},done(){if(this.owner)uni.setStorageSync('lawyerOnboarding:v1:'+this.owner,true);this.visible=false;},next(){if(this.step<2)this.step++;else this.done();}}};
</script><style scoped>.overlay{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.4);padding:40rpx}.dialog{background:#fff;border-radius:24rpx;padding:36rpx;width:100%;max-width:580rpx}.dialog text{display:block;line-height:1.8;margin:18rpx 0;font-size:16px;color:var(--brand-text)}.title{font-size:20px!important;font-weight:600}.heading{font-weight:600}.dialog button{margin:18rpx}</style>
